/*
 * mac_array_ckpt_dump.cpp -- A2 exit measurement (ZHR-92, 2026-08-21).
 *
 * Runs the REAL 82-entry hardware sequence (mac_array_ckpt_desc.h,
 * generated by tools/gen_ckpt_harness.py from layer_hw_sequence_256.json
 * + the real gamma-folded weights) against the real test image's Stem
 * output (computed ARM-side, tools/compute_stem_arm.py -- Route C, see
 * ZHR-92/ZHR-64), dumping each of the 6 hardware-side checkpoints
 * (stage1..4, finaldw, se) to its own .bin for comparison against the
 * float32 ONNX reference (tools/gen_ckpt_reference_256.py). The 7th
 * checkpoint (stem) needs no hardware run at all -- it's ARM's own
 * output, compared directly.
 *
 * Entries are dispatched ONE AT A TIME (not n_layers=82 in one call) so a
 * checkpoint dump can happen between entries -- mac_array_top itself just
 * loops over whatever n_layers it's given, so this is behaviorally
 * identical to a single 82-entry call, just with observation points.
 */
#include "mac_array.h"
#include "mac_array_ckpt_desc.h"
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>

static std::vector<int8_t> read_file_i8(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::vector<int8_t> buf(sz);
    fread(buf.data(), 1, sz, f);
    fclose(f);
    return buf;
}

static std::vector<int32_t> read_file_i32(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::vector<int32_t> buf(sz / 4);
    fread(buf.data(), 1, sz, f);
    fclose(f);
    return buf;
}

int main() {
    setvbuf(stdout, nullptr, _IONBF, 0);
    const int TOTAL_BYTES = 1819392;  // tools/layer_hw_sequence_256.json's total_bytes

    std::vector<int8_t> stem_out = read_file_i8(
        "E:\\codes\\microzed\\fastvit_hls\\accuracy_test_imgs_256\\stem_output_0000.bin");
    printf(">>> loaded Stem ARM output: %zu bytes\n", stem_out.size());

    std::vector<int8_t> w_flat = read_file_i8(
        "E:\\codes\\microzed\\fastvit_hls\\fastvit_ip_v2\\ckpt_weights_flat.bin");
    std::vector<int32_t> b_flat = read_file_i32(
        "E:\\codes\\microzed\\fastvit_hls\\fastvit_ip_v2\\ckpt_bias_flat.bin");
    printf(">>> loaded weights: %zu bytes, bias: %zu words\n", w_flat.size(), b_flat.size());

    std::vector<act_t> act_buf(TOTAL_BYTES, act_t(0));
    std::vector<wt_t>  w_buf(w_flat.size(), wt_t(0));
    std::vector<acc_t> b_buf(b_flat.size(), acc_t(0));
    for (size_t i = 0; i < w_flat.size(); i++) w_buf[i] = wt_t(w_flat[i]);
    for (size_t i = 0; i < b_flat.size(); i++) b_buf[i] = acc_t(b_flat[i]);

    // Stem's ARM-computed output lands at MAIN0 (offset 0) -- same buffer
    // role the raw image used to play, before Route C.
    for (size_t i = 0; i < stem_out.size(); i++) act_buf[i] = act_t(stem_out[i]);

    set_shift_table_fields();

    for (int i = 0; i < N_HW_SEQ; i++) {
        MacArrayParams p = derive_mac_array_params(g_hw_seq[i]);
        g_hw_seq[i].h_out = p.h_out; g_hw_seq[i].w_out = p.w_out;
        g_hw_seq[i].n_row_tiles = p.n_row_tiles; g_hw_seq[i].n_col_tiles = p.n_col_tiles;
        g_hw_seq[i].n_ch_tiles = p.n_ch_tiles;
        g_hw_seq[i].last_row_tile = p.last_row_tile; g_hw_seq[i].last_col_tile = p.last_col_tile;
        g_hw_seq[i].last_ch_tile = p.last_ch_tile;
        g_hw_seq[i].in_ch_stride = p.in_ch_stride; g_hw_seq[i].out_ch_stride = p.out_ch_stride;
    }

    printf(">>> running %d hardware entries...\n", N_HW_SEQ);
    int ckpt_cursor = 0;
    for (int i = 0; i < N_HW_SEQ; i++) {
        printf("  entry %d: op_type=%d cin=%d cout=%d h_in=%d w_in=%d k=%d in_off=%d w_off=%d b_off=%d out_off=%d in2_off=%d\n",
               i, g_hw_seq[i].op_type, g_hw_seq[i].cin, g_hw_seq[i].cout, g_hw_seq[i].h_in, g_hw_seq[i].w_in,
               g_hw_seq[i].k, g_hw_seq[i].in_off, g_hw_seq[i].w_off, g_hw_seq[i].b_off, g_hw_seq[i].out_off, g_hw_seq[i].in2_off);
        int written[1] = {0};
        mac_array_top(&g_hw_seq[i], 1, act_buf.data(), w_buf.data(), b_buf.data(), act_buf.data(), written);

        // A2 Phase C diagnostic (2026-08-21, ZHR-92): dump EVERY entry's
        // full output in the stem.1..stage1 span (entries 0-16) for a
        // layer-by-layer paired comparison against a bit-exact Python
        // simulator -- localizes exactly where the 26pp gap between the
        // idealized Python quantization model and real hardware starts.
        if (i <= 16) {
            int size = g_hw_seq[i].cout * g_hw_seq[i].h_out * g_hw_seq[i].w_out;
            char path[256];
            snprintf(path, sizeof(path),
                     "E:\\codes\\microzed\\fastvit_hls\\accuracy_test_imgs_256\\entry_%02d.bin", i);
            FILE *ef = fopen(path, "wb");
            for (int k = 0; k < size; k++) {
                int8_t v = (int8_t)act_buf[g_hw_seq[i].out_off + k];
                fwrite(&v, 1, 1, ef);
            }
            fclose(ef);
        }

        while (ckpt_cursor < N_CKPT && g_ckpts[ckpt_cursor].seq_index == i) {
            const CkptEntry &ck = g_ckpts[ckpt_cursor];
            std::string path = std::string("E:\\codes\\microzed\\fastvit_hls\\accuracy_test_imgs_256\\ckpt_hw_")
                                + ck.tag + "_0000.bin";
            FILE *f = fopen(path.c_str(), "wb");
            for (int k = 0; k < ck.size; k++) {
                int8_t v = (int8_t)act_buf[ck.out_off + k];
                fwrite(&v, 1, 1, f);
            }
            fclose(f);
            printf("  [%3d] dumped checkpoint '%s' -> %s (%d bytes)\n", i, ck.tag, path.c_str(), ck.size);
            ckpt_cursor++;
        }
    }

    printf(">>> done, %d/%d checkpoints dumped\n", ckpt_cursor, N_CKPT);
    return (ckpt_cursor == N_CKPT) ? 0 : 1;
}
